select
    DATE(order_time) day ,SUM(amount) AS turnover
from orders WHERE order_time >= CURDATE() - INTERVAL 6 DAY AND orders.order_time < CURDATE() + INTERVAL 1 DAY GROUP BY DATE(order_time)

SELECT
        (SELECT COUNT(*) FROM dish    WHERE status = 1) AS dishes,
        (SELECT COUNT(*) FROM setmeal WHERE status = 1) AS setmeals;
